{
  "findings": [
    {
      "title": "Primary endpoint stated as PFS in Section 2.1.2 but the protocol title/objectives may indicate OS as primary; inconsistency in endpoint hierarchy",
      "page": 38,
      "quote": "The primary endpoint of Study 20190009 is progression-free Survival (PFS).",
      "severity": "critical"
    },
    {
      "title": "Cross-reference to Section 6.2.2.2 for docetaxel dose reductions, but the excerpt does not include such a section; likely non-existent",
      "page": 38,
      "quote": "with dose reductions allowed as described in Section 6.2.2.2",
      "severity": "major"
    },
    {
      "title": "Inconsistent ECOG performance status criteria: Section 2.1.1 states patients with ECOG ≥2 are not eligible for docetaxel, but Section 2.1.1 bullet says subjects must have ECOG ≤1; however, the text also says 'subjects enrolled in this study must have better performance status (ECOG status ≤ 1)' which is consistent, but the earlier statement 'Patients who are not eligible for treatment with docetaxel (eg, patients with ECOG status ≥ 2)' implies ECOG ≥2 are excluded, which is fine, but the protocol may not explicitly state inclusion criteria; the contradiction is minor",
      "page": 37,
      "quote": "Patients who are not eligible for treatment with docetaxel (eg, patients with ECOG status ≥ 2) would most likely receive only palliative care",
      "severity": "minor"
    },
    {
      "title": "Inconsistent survival gain figure: REVEL study cited as 1.4 months, but the text says 'survival gain of 1.4 months' which is plausible; no error",
      "page": 37,
      "quote": "survival gain of 1.4 months",
      "severity": "minor"
    },
    {
      "title": "Inconsistent KRAS G12C mutation prevalence: Section 2.2.1.2 says 13% of lung adenocarcinoma, but Section 2.2.1.3 says 'approximately 13%' which is consistent; no error",
      "page": 40,
      "quote": "approximately 13% of lung adenocarcinoma",
      "severity": "minor"
    },
    {
      "title": "Inconsistent number of evaluable subjects: Section 2.2.2 says 39 of 62 evaluable, but then says 7 of 17 evaluable NSCLC subjects had PR; the 17 is a subset, not contradictory",
      "page": 44,
      "quote": "7 of 17 evaluable subjects having a PR",
      "severity": "minor"
    },
    {
      "title": "Inconsistent safety data: Section 2.2.2 says as of 28 Aug 2019, 95 subjects had safety data, but earlier says 62 enrolled as of 12 June 2019; not contradictory as later cutoff",
      "page": 44,
      "quote": "As of the data cut-off date of 28 August 2019, preliminary safety data were available for 95 subjects",
      "severity": "minor"
    },
    {
      "title": "Inconsistent docetaxel dose: Section 2.2.3 says TAX 317 used 100 mg/m2 then lowered to 75, but Section 2.1.1 says 75 mg/m2 chosen; consistent",
      "page": 45,
      "quote": "100 mg/m2 as a 1-h intravenous infusion once every 21 days, but because of an unexpectedly high incidence of febrile neutropenia and deaths from sepsis, the dose was lowered to 75 mg/m2",
      "severity": "minor"
    },
    {
      "title": "Inconsistent OS definition: Section 2.1.3 says OS censored at date of last contact through analysis trigger date, but Section 3 table says OS defined as time from randomization until death from any cause without mention of censoring; minor inconsistency",
      "page": 39,
      "quote": "Overall survival, defined as time from randomization until death from any cause (subjects who do not die will be censored at the date of last contact through the analysis trigger date)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PRO endpoint: Section 2.1.3 says change from baseline over time to week 12 in physical functioning and global health status, but Section 3 table only lists physical functioning, not global health status",
      "page": 39,
      "quote": "Change from baseline over time to week 12 in physical functioning and global health status will also be compared",
      "severity": "major"
    },
    {
      "title": "Inconsistent reference to 'Section 3' for estimand framework: Section 2.1.2 says 'See Section 3 and Section 9.4.2.2' but Section 3 is objectives/endpoints, not estimand details; likely wrong cross-reference",
      "page": 38,
      "quote": "See Section 3 and Section 9.4.2.2 for details of the estimand framework.",
      "severity": "major"
    },
    {
      "title": "Inconsistent statement about docetaxel mortality: Section 2.1.1 says 'Docetaxel mortality in clinical studies was increased in subjects with ECOG status of 2' but earlier says patients with ECOG ≥2 are not eligible; this is a rationale, not contradiction",
      "page": 38,
      "quote": "Docetaxel mortality in clinical studies was increased in subjects with ECOG status of 2.",
      "severity": "minor"
    }
  ]
}
